INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('4011f851-ab18-4fd4-a27a-1e4fdc99f3b1', '48313476-5de3-4ca6-bb66-4ec5318918bd', 'Sobre o direito de propriedade, conforme a Constituição Federal, assinale a alternativa correta.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Câmara de Cordilheira Alta Camara de Cordilheira Alta - SC / Procurador Legislativo / Questão: 12', 'O art. 5º, XXII e XXIII, dispõe que "é garantido o direito de propriedade" e que "a propriedade atenderá a sua função social". A alternativa "c" une corretamente os dois incisos. As demais erram ao tratar o direito como absoluto/ilimitado ("a"), ao limitar a restrição apenas ao tempo de guerra ("b" — há diversas outras hipóteses, como a desapropriação e o uso de propriedade particular em perigo público), ao afirmar que a função social é facultativa ("d" — é dever constitucional, não faculdade) e ao negar qualquer restrição legal ("e" — a própria função social já é uma limitação).', 1, true),
('4a0bb773-683d-4908-b9e9-9363a4ce157d', '48313476-5de3-4ca6-bb66-4ec5318918bd', 'Um grupo de moradores de determinado bairro decidiu se organizar para "patrulhar" as ruas durante a noite, portando armas de fogo, sob a justificativa de proteger a comunidade contra a criminalidade. Com base na liberdade de associação garantida pela Constituição Federal, esse grupo:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Segredo - RS / Mecânico / Questão: 24', 'O art. 5º, XVII, veda expressamente a associação de caráter paramilitar, o que torna ilegítima qualquer organização civil armada com finalidade de patrulhamento à revelia do Estado. As demais alternativas tentam justificar a atuação armada sob condições (horário, treinamento, voluntariado, registro informal) que não afastam a vedação constitucional.', 2, true),
('613e01dc-79da-4176-a0d1-936ce44f4800', '48313476-5de3-4ca6-bb66-4ec5318918bd', 'Determinado órgão público pretendia impedir a circulação de um panfleto de crítica política a uma gestão municipal, sob a alegação de que o conteúdo poderia ser considerado ofensivo. Considerando a Constituição Federal, é correto afirmar que:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Serviço de Água e Esgotos SAMAE de Sao Leopoldo - RS / Agente Operacional / Questão: 23', 'O art. 5º, IX, garante a livre expressão da atividade intelectual, artística, científica e de comunicação "independentemente de censura ou licença", vedação absoluta que abrange qualquer natureza de censura (política, ideológica ou artística). As demais alternativas tentam criar exceções (proteção da ordem pública, autorização do STF, distinção entre censura política e artística) que não encontram amparo no texto constitucional.', 3, true),
('8b89477b-07ad-427d-b222-02e670050b2c', '48313476-5de3-4ca6-bb66-4ec5318918bd', 'Segundo os termos do art. 5º da Constituição Federal, são invioláveis a ____________________ e a honra das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação. Assinale a alternativa que preenche corretamente a lacuna do trecho acima.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Prefeitura de Coronel Pilar - RS / Motorista / Questão: 21', 'O art. 5º, X, dispõe que "são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas". A alternativa "e" preenche corretamente as lacunas com "intimidade, a vida privada, a imagem". As demais utilizam expressões estranhas ao dispositivo constitucional.', 4, true),
('2ced9350-6f7d-4f75-87dc-fe37838a6e10', '48313476-5de3-4ca6-bb66-4ec5318918bd', 'Dentre as garantias processuais previstas no art. 5º da Constituição Federal, NÃO é considerado como tal o "princípio" do(a):', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Instituto Federal Catarinense IFC - BR / Professor de Ensino Básico, Técnico e Tecnológico - Área: Direito / Questão: 25', 'O art. 5º, XXXVII, dispõe que "não haverá" juízo ou tribunal de exceção — trata-se de uma vedação, e não de um "direito" à existência de tribunal de exceção, o que torna essa formulação incorreta como garantia processual. As demais (a, c, d, e) correspondem, respectivamente, aos incisos LIV, XXXV, LV e LV do art. 5º.', 5, true),
('55868a8d-0f03-447e-80f0-713abf07c873', '48313476-5de3-4ca6-bb66-4ec5318918bd', 'De acordo com a Constituição Federal, todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade. Sendo assim, assinale a alternativa INCORRETA.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2021 / Prefeitura de Ivoti - RS / Operador de Máquinas / Questão: 29', 'A alternativa "e" é a incorreta, pois contraria o art. 5º, I: homens e mulheres são iguais, e não desiguais, em direitos e obrigações. As demais (a, b, c, d) reproduzem corretamente os incisos II, IV, VI e III do art. 5º.', 6, true),
('1ae6ad52-f784-4b29-8bc3-fd5ae710810e', '48313476-5de3-4ca6-bb66-4ec5318918bd', 'Sobre os remédios constitucionais, assinale a alternativa correta.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Venâncio Aires - RS / Assistente Jurídico / Questão: 32', 'A alternativa B transcreve o art. 5º, LXXII, "b", CF: "conceder-se-á habeas data: (...) b) para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo."
INSERT INTO public.questao_alternativas (questao_id, letra, texto, correta, ordem) VALUES
('4011f851-ab18-4fd4-a27a-1e4fdc99f3b1', 'A', 'É garantido o direito de propriedade de forma absoluta e ilimitada.', false, 0),
('4011f851-ab18-4fd4-a27a-1e4fdc99f3b1', 'B', 'A propriedade privada pode ser limitada apenas em tempo de guerra.', false, 1),
('4011f851-ab18-4fd4-a27a-1e4fdc99f3b1', 'C', 'É garantido o direito de propriedade, que atenderá a sua função social.', true, 2),
('4011f851-ab18-4fd4-a27a-1e4fdc99f3b1', 'D', 'A função social da propriedade é facultativa ao proprietário.', false, 3),
('4011f851-ab18-4fd4-a27a-1e4fdc99f3b1', 'E', 'O direito de propriedade não pode sofrer restrições legais.', false, 4),
('4a0bb773-683d-4908-b9e9-9363a4ce157d', 'A', 'Pode patrulhar o bairro utilizando armas apenas durante a noite.', false, 0),
('4a0bb773-683d-4908-b9e9-9363a4ce157d', 'B', 'Tem o direito de atuar armado, desde que seus membros possuam treinamento em segurança pública.', false, 1),
('4a0bb773-683d-4908-b9e9-9363a4ce157d', 'C', 'Não pode atuar de forma armada ou militarizada, pois isso configura uma associação de caráter paramilitar, o que é vedado pela Constituição.', true, 2),
('4a0bb773-683d-4908-b9e9-9363a4ce157d', 'D', 'Pode operar como uma associação armada, contanto que todas as suas atividades sejam voluntárias e não remuneradas.', false, 3),
('4a0bb773-683d-4908-b9e9-9363a4ce157d', 'E', 'Tem o direito de se registrar como empresa de segurança privada e, assim, patrulhar o bairro utilizando armas, mesmo sem seguir as regulamentações legais para empresas de segurança.', false, 4),
('613e01dc-79da-4176-a0d1-936ce44f4800', 'A', 'Toda e qualquer forma de censura de natureza política, ideológica e artística é proibida.', true, 0),
('613e01dc-79da-4176-a0d1-936ce44f4800', 'B', 'A censura prévia é permitida em casos de manifestações artísticas que envolvam nudez.', false, 1),
('613e01dc-79da-4176-a0d1-936ce44f4800', 'C', 'A censura ideológica pode ser aplicada para proteger a ordem pública.', false, 2),
('613e01dc-79da-4176-a0d1-936ce44f4800', 'D', 'A censura política é vedada, mas a censura artística pode ser aplicada em casos excepcionais.', false, 3),
('613e01dc-79da-4176-a0d1-936ce44f4800', 'E', 'A censura é permitida desde que seja autorizada pelo Supremo Tribunal Federal.', false, 4),
('8b89477b-07ad-427d-b222-02e670050b2c', 'A', 'privacidade digital, a hora extra, a vida pública', false, 0),
('8b89477b-07ad-427d-b222-02e670050b2c', 'B', 'intimidade, a dedicação ao lazer, a comunicação escrita', false, 1),
('8b89477b-07ad-427d-b222-02e670050b2c', 'C', 'privacidade digital, a hora extra, a intimidade', false, 2),
('8b89477b-07ad-427d-b222-02e670050b2c', 'D', 'transparência, a vida pública, a imagem', false, 3),
('8b89477b-07ad-427d-b222-02e670050b2c', 'E', 'intimidade, a vida privada, a imagem', true, 4),
('2ced9350-6f7d-4f75-87dc-fe37838a6e10', 'A', 'Devido processo legal.', false, 0),
('2ced9350-6f7d-4f75-87dc-fe37838a6e10', 'B', 'Direito a juízo ou tribunal de exceção.', true, 1),
('2ced9350-6f7d-4f75-87dc-fe37838a6e10', 'C', 'Acesso à justiça.', false, 2),
('2ced9350-6f7d-4f75-87dc-fe37838a6e10', 'D', 'Direito ao contraditório.', false, 3),
('2ced9350-6f7d-4f75-87dc-fe37838a6e10', 'E', 'Direito à ampla defesa.', false, 4),
('55868a8d-0f03-447e-80f0-713abf07c873', 'A', 'Ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei.', false, 0),
('55868a8d-0f03-447e-80f0-713abf07c873', 'B', 'É livre a manifestação do pensamento, sendo vedado o anonimato.', false, 1),
('55868a8d-0f03-447e-80f0-713abf07c873', 'C', 'É inviolável a liberdade de consciência e de crença, sendo assegurado o livre exercício dos cultos religiosos e garantida, na forma da lei, a proteção aos locais de culto e a suas liturgias.', false, 2),
('55868a8d-0f03-447e-80f0-713abf07c873', 'D', 'Ninguém será submetido a tortura nem a tratamento desumano ou degradante.', false, 3),
('55868a8d-0f03-447e-80f0-713abf07c873', 'E', 'Homens e mulheres são desiguais em direitos e obrigações.', true, 4),
('1ae6ad52-f784-4b29-8bc3-fd5ae710810e', 'A', 'É constitucional a limitação dos efeitos da coisa julgada produzida nas ações civil pública aos limites da competência territorial do órgão prolator.', false, 0),
('1ae6ad52-f784-4b29-8bc3-fd5ae710810e', 'B', 'Conceder-se-á habeas data para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo.', true, 1),
('1ae6ad52-f784-4b29-8bc3-fd5ae710810e', 'C', 'Pessoa jurídica de direito privado pode pleitear a anulação ou a declaração de nulidade de atos lesivos ao patrimônio da União, do Distrito Federal, dos Estados, dos Municípios, de entidades autárquicas, de sociedades de economia mista.', false, 2),
('1ae6ad52-f784-4b29-8bc3-fd5ae710810e', 'D', 'Em sede de mandado de injunção, não poderá ser conferida eficácia ultra partes ou erga omnes à decisão.', false, 3),
('1ae6ad52-f784-4b29-8bc3-fd5ae710810e', 'E', 'É constitucional ato normativo que vede ou condicione a concessão de medida liminar na via mandamental.', false, 4);